  9	import com.loja.orderservice.repository.CustomerRepository;
 10	import org.springframework.http.HttpStatus;
 11	import org.springframework.http.ResponseEntity;
 12	import org.springframework.web.bind.annotation.*;
 13	
 14	import java.util.List;
 15	import java.util.stream.Collectors;
 16	
 17	@RestController
 18	@RequestMapping("/")
 19	public class CustomerController {
 20	    private final CustomerRepository customerRepository;
 21	    private final CustomerNotificationRepository notificationRepository;
 22	
 23	    public CustomerController(CustomerRepository customerRepository, CustomerNotificationRepository notificationRepository) {
 24	        this.customerRepository = customerRepository;
 25	        this.notificationRepository = notificationRepository;
 26	    }
 27	
 28	    @GetMapping("/customers/{cpf}")
 29	    public ResponseEntity<?> getCustomer(@PathVariable String cpf) {
 30	        var customer = customerRepository.findById(cpf);
 31	        if (customer.isEmpty()) {
 32	            return ResponseEntity.status(HttpStatus.NOT_FOUND)
 33	                .body(new ErrorResponseDTO("CUSTOMER_NOT_FOUND"));
 34	        }
 35	
 36	        var c = customer.get();
 37	        CustomerResponseDTO response = new CustomerResponseDTO(c.getCpf(), c.getCreditBalance());
 38	        return ResponseEntity.ok(response);
 39	    }
 40	
 41	    @GetMapping("/customers/{cpf}/notifications")
 42	    public ResponseEntity<?> getNotifications(@PathVariable String cpf) {
 43	        List<CustomerNotification> notifications = notificationRepository.findByCpf(cpf);
 44	
 45	        if (notifications.isEmpty() && customerRepository.findById(cpf).isEmpty()) {
 46	            return ResponseEntity.status(HttpStatus.NOT_FOUND)
 47	                .body(new ErrorResponseDTO("CUSTOMER_NOT_FOUND"));
 48	        }
 49	
 50	        List<NotificationResponseDTO> response = notifications.stream()
 51	            .map(n -> new NotificationResponseDTO(n.getId(), n.getType(), n.getOrderId(), n.getStatus()))
 52	            .collect(Collectors.toList());
 53	
 54	        return ResponseEntity.ok(response);
 55	    }
 56	
 57	    @PostMapping("/notifications/{id}/read")
 58	    public ResponseEntity<?> markNotificationAsRead(@PathVariable String id) {
 59	        var notification = notificationRepository.findById(id);
 60	        if (notification.isEmpty()) {
 61	            return ResponseEntity.status(HttpStatus.NOT_FOUND)
 62	                .body(new ErrorResponseDTO("NOTIFICATION_NOT_FOUND"));
 63	        }
 64	
 65	        var n = notification.get();
 66	        n.setStatus(NotificationStatus.READ);
 67	        notificationRepository.save(n);
 68	        NotificationResponseDTO response = new NotificationResponseDTO(
 69	            n.getId(),
 70	            n.getType(),
 71	            n.getOrderId(),
 72	            n.getStatus()
 73	        );
 74	        return ResponseEntity.ok(response);
 75	    }
 76	}
