 97	        this.orderService = orderService;
 98	    }
 99	
100	    @PostMapping("/checkout/summary")
101	    public ResponseEntity<?> calculateSummary(@RequestBody OrderRequestDTO request) {
102	        try {
103	            OrderSummary summary = orderService.calculateSummary(request);
104	            SummaryResponseDTO response = convertToSummaryDTO(summary);
105	            return ResponseEntity.ok(response);
106	        } catch (OrderException e) {
