111	    @PostMapping("/orders")
112	    public ResponseEntity<?> createOrder(@RequestBody OrderRequestDTO request) {
113	        try {
114	            Order order = orderService.createOrder(request);
115	            OrderResponseDTO response = convertToOrderDTO(order);
116	            return ResponseEntity.status(HttpStatus.CREATED).body(response);
117	        } catch (OrderException e) {
118	            return ResponseEntity.status(e.getHttpStatus()).body(new ErrorResponseDTO(e.getErrorCode()));
119	        }
120	    }
121	
122	    @GetMapping("/orders/{id}")
123	    public ResponseEntity<?> getOrder(@PathVariable String id) {
124	        try {
125	            Order order = orderService.getOrder(id);
126	            OrderResponseDTO response = convertToOrderDTO(order);
127	            return ResponseEntity.ok(response);
128	        } catch (OrderException e) {
129	            return ResponseEntity.status(e.getHttpStatus()).body(new ErrorResponseDTO(e.getErrorCode()));
130	        }
131	    }
132	
133	    @PostMapping("/orders/{id}/payment")
134	    public ResponseEntity<?> processPayment(@PathVariable String id, @RequestBody PaymentRequestDTO request) {
135	        try {
136	            if (request.getTransactionId() == null || request.getPaidAt() == null) {
137	                return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY)
138	                    .body(new ErrorResponseDTO("INVALID_ORDER"));
139	            }
140	
141	            Order order = orderService.processPayment(id, request.getTransactionId(), request.getPaidAt());
142	            OrderResponseDTO response = convertToOrderDTO(order);
143	            return ResponseEntity.ok(response);
144	        } catch (OrderException e) {
145	            return ResponseEntity.status(e.getHttpStatus()).body(new ErrorResponseDTO(e.getErrorCode()));
146	        }
147	    }
