149	    @PostMapping("/orders/{id}/shipment")
150	    public ResponseEntity<?> shipOrder(@PathVariable String id, @RequestBody ShipmentRequestDTO request) {
151	        try {
152	            if (request.getTrackingCode() == null) {
153	                return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY)
154	                    .body(new ErrorResponseDTO("INVALID_ORDER"));
155	            }
156	
157	            Order order = orderService.shipOrder(id, request.getTrackingCode());
158	            OrderResponseDTO response = convertToOrderDTO(order);
159	            return ResponseEntity.ok(response);
160	        } catch (OrderException e) {
161	            return ResponseEntity.status(e.getHttpStatus()).body(new ErrorResponseDTO(e.getErrorCode()));
162	        }
163	    }
164	
165	    @PostMapping("/orders/{id}/delivery")
166	    public ResponseEntity<?> deliverOrder(@PathVariable String id) {
167	        try {
168	            Order order = orderService.deliverOrder(id);
169	            OrderResponseDTO response = convertToOrderDTO(order);
170	            return ResponseEntity.ok(response);
171	        } catch (OrderException e) {
172	            return ResponseEntity.status(e.getHttpStatus()).body(new ErrorResponseDTO(e.getErrorCode()));
173	        }
174	    }
175	
176	    @PostMapping("/orders/{id}/cancellation")
177	    public ResponseEntity<?> cancelOrder(@PathVariable String id) {
178	        try {
179	            Order order = orderService.cancelOrder(id);
180	            OrderResponseDTO response = convertToOrderDTO(order);
181	            return ResponseEntity.ok(response);
182	        } catch (OrderException e) {
183	            return ResponseEntity.status(e.getHttpStatus()).body(new ErrorResponseDTO(e.getErrorCode()));
184	        }
185	    }
186	
187	    private OrderResponseDTO convertToOrderDTO(Order order) {
188	        java.util.List<OrderItemDTO> items = order.getItems().stream()
189	            .map(item -> new OrderItemDTO(item.getSku(), item.getQuantity()))
190	            .collect(Collectors.toList());
191	
192	        return new OrderResponseDTO(
193	            order.getId(),
194	            order.getStatus(),
195	            order.getCreatedAt(),
196	            order.getSummary(),
197	            items,
198	            order.getTrackingCode()
199	        );
200	    }
201	
202	    private SummaryResponseDTO convertToSummaryDTO(OrderSummary summary) {
203	        return new SummaryResponseDTO(
204	            summary.getProductsSubtotal(),
205	            summary.getCouponDiscount(),
206	            summary.getShippingCost(),
207	            summary.getDeliveryDays(),
208	            summary.getInsurance(),
209	            summary.getPaymentAdjustment(),
210	            summary.getFinalTotal(),
211	            summary.getInstallments(),
212	            summary.getInstallmentAmount(),
213	            summary.getNextPurchaseCredit(),
214	            summary.getGift()
215	        );
216	    }
217	}
