  2	
  3	import com.loja.orderservice.client.TransLogClient;
  4	import com.loja.orderservice.dto.OrderItemDTO;
  5	import com.loja.orderservice.dto.OrderRequestDTO;
  6	import com.loja.orderservice.entity.*;
  7	import com.loja.orderservice.exception.OrderException;
  8	import com.loja.orderservice.repository.ProductRepository;
  9	import com.loja.orderservice.util.PricingUtil;
 10	import org.springframework.http.HttpStatus;
 11	import org.springframework.stereotype.Service;
 12	
 13	import java.math.BigDecimal;
 14	import java.util.List;
 15	import java.util.Optional;
 16	
 17	@Service
 18	public class PricingService {
 19	    private final ProductRepository productRepository;
 20	    private final TransLogClient transLogClient;
 21	
 22	    public PricingService(ProductRepository productRepository, TransLogClient transLogClient) {
 23	        this.productRepository = productRepository;
 24	        this.transLogClient = transLogClient;
 25	    }
 26	
 27	    public OrderSummary calculateSummary(OrderRequestDTO request) {
 28	        BigDecimal productsSubtotal = calculateProductsSubtotal(request.getItems());
 29	        BigDecimal couponDiscount = calculateCouponDiscount(request.getCoupon(), productsSubtotal, request.getShippingMethod(), request);
 30	
 31	        ShippingCostInfo shippingInfo = calculateShippingCost(request);
 32	        BigDecimal shippingCost = shippingInfo.cost;
 33	        Integer deliveryDays = shippingInfo.days;
 34	
 35	        BigDecimal insurance = calculateInsurance(productsSubtotal, request.getRegion());
 36	
 37	        BigDecimal subtotalBeforePayment = PricingUtil.add(
 38	            PricingUtil.subtract(productsSubtotal, couponDiscount),
 39	            PricingUtil.add(shippingCost, insurance)
 40	        );
 41	
 42	        validatePaymentMethodConstraints(request, subtotalBeforePayment);
 43	
 44	        PaymentAdjustmentInfo adjustmentInfo = calculatePaymentAdjustment(
 45	            request.getPaymentMethod(),
 46	            subtotalBeforePayment,
 47	            request.getInstallments(),
 48	            request.getCoupon() != null && !request.getCoupon().isEmpty()
 49	        );
 50	
 51	        BigDecimal finalTotal = adjustmentInfo.finalTotal;
 52	        Integer installments = adjustmentInfo.installments;
 53	        BigDecimal installmentAmount = adjustmentInfo.installmentAmount;
 54	
 55	        BigDecimal nextPurchaseCredit = calculateNextPurchaseCredit(request.getClubTier(), productsSubtotal);
 56	
 57	        Boolean gift = shouldGiveGift(request.getClubTier(), productsSubtotal);
 58	
 59	        return new OrderSummary(
 60	            productsSubtotal,
 61	            couponDiscount,
 62	            shippingCost,
 63	            deliveryDays,
 64	            insurance,
 65	            adjustmentInfo.adjustment,
 66	            finalTotal,
 67	            installments,
 68	            installmentAmount,
 69	            nextPurchaseCredit,
 70	            gift
 71	        );
 72	    }
 73	
 74	    private BigDecimal calculateProductsSubtotal(List<OrderItemDTO> items) {
 75	        BigDecimal subtotal = BigDecimal.ZERO;
 76	        for (OrderItemDTO item : items) {
 77	            Optional<Product> product = productRepository.findById(item.getSku());
 78	            if (product.isPresent()) {
 79	                BigDecimal itemPrice = PricingUtil.multiply(product.get().getPrice(), new BigDecimal(item.getQuantity()));
 80	                subtotal = PricingUtil.add(subtotal, itemPrice);
 81	            }
 82	        }
 83	        return subtotal;
 84	    }
 85	
 86	    private BigDecimal calculateCouponDiscount(String coupon, BigDecimal subtotal, ShippingMethod shippingMethod, OrderRequestDTO request) {
 87	        if (coupon == null || coupon.isEmpty()) {
 88	            return BigDecimal.ZERO;
 89	        }
 90	
 91	        BigDecimal discount = BigDecimal.ZERO;
 92	
 93	        if ("WELCOME10".equals(coupon)) {
 94	            discount = PricingUtil.percentage(subtotal, new BigDecimal("10"));
 95	        } else if ("MINUS50".equals(coupon)) {
 96	            if (subtotal.compareTo(new BigDecimal("300")) >= 0) {
 97	                discount = new BigDecimal("50.00");
 98	            }
 99	        } else if ("FREESHIPPING".equals(coupon)) {
100	            ShippingCostInfo shippingInfo = calculateShippingCost(request);
101	            discount = shippingInfo.cost;
102	        } else if ("BUY3PAY2".equals(coupon)) {
103	            discount = calculateBuy3Pay2Discount(request.getItems());
104	        }
105	
106	        BigDecimal maxDiscount = PricingUtil.percentage(subtotal, new BigDecimal("30"));
107	        if (discount.compareTo(maxDiscount) > 0) {
108	            discount = maxDiscount;
109	        }
110	
111	        return discount;
112	    }
113	
114	    private BigDecimal calculateBuy3Pay2Discount(List<OrderItemDTO> items) {
115	        BigDecimal discount = BigDecimal.ZERO;
116	
117	        for (OrderItemDTO item : items) {
118	            Optional<Product> product = productRepository.findById(item.getSku());
119	            if (product.isPresent()) {
120	                int quantity = item.getQuantity();
121	                int freeItems = quantity / 3;
122	                if (freeItems > 0) {
123	                    BigDecimal itemDiscount = PricingUtil.multiply(product.get().getPrice(), new BigDecimal(freeItems));
124	                    discount = PricingUtil.add(discount, itemDiscount);
125	                }
126	            }
127	        }
128	
129	        return discount;
130	    }
131	
132	    private class ShippingCostInfo {
133	        BigDecimal cost;
134	        Integer days;
135	
136	        ShippingCostInfo(BigDecimal cost, Integer days) {
137	            this.cost = cost;
138	            this.days = days;
139	        }
140	    }
141	
142	    private ShippingCostInfo calculateShippingCost(OrderRequestDTO request) {
143	        ShippingMethod method = request.getShippingMethod();
144	        Region region = request.getRegion();
145	        String zipCode = request.getZipCode();
146	        BigDecimal weight = calculateWeight(request.getItems());
147	
148	        if (method == ShippingMethod.STORE_PICKUP) {
149	            return new ShippingCostInfo(BigDecimal.ZERO, 1);
150	        }
151	
152	        if (method == ShippingMethod.COURIER) {
153	            if (weight.compareTo(new BigDecimal("5")) > 0) {
154	                throw new OrderException("SHIPPING_METHOD_UNAVAILABLE", "COURIER max weight is 5kg", HttpStatus.UNPROCESSABLE_ENTITY);
155	            }
156	            return new ShippingCostInfo(new BigDecimal("18.00"), 0);
157	        }
158	
159	        try {
160	            String service = method == ShippingMethod.ECONOMY ? "STD" : "EXP";
161	            TransLogClient.TransLogQuote quote = transLogClient.getQuote(zipCode, weight.multiply(new BigDecimal("1000")).intValue(), service);
162	
163	            BigDecimal cost = PricingUtil.round(quote.getPrice());
164	            int days = PricingUtil.ceilDays(quote.etaHours);
165	
166	            if (region == Region.NORTH && (method == ShippingMethod.ECONOMY || method == ShippingMethod.EXPRESS)) {
167	                days += 3;
168	            } else if (region == Region.NORTHEAST && (method == ShippingMethod.ECONOMY || method == ShippingMethod.EXPRESS)) {
169	                days += 2;
170	            }
171	
172	            return new ShippingCostInfo(cost, days);
173	        } catch (TransLogClient.TransLogException e) {
174	            if ("ZIP_NOT_SERVED".equals(e.getMessage())) {
175	                throw new OrderException("SHIPPING_METHOD_UNAVAILABLE", "TransLog does not serve this ZIP", HttpStatus.UNPROCESSABLE_ENTITY);
176	            }
177	            throw new OrderException("CARRIER_UNAVAILABLE", "TransLog is unavailable", HttpStatus.SERVICE_UNAVAILABLE);
178	        }
179	    }
