181	    private BigDecimal calculateWeight(List<OrderItemDTO> items) {
182	        BigDecimal totalWeight = BigDecimal.ZERO;
183	        for (OrderItemDTO item : items) {
184	            Optional<Product> product = productRepository.findById(item.getSku());
185	            if (product.isPresent()) {
186	                BigDecimal itemWeight = product.get().getWeightKg().multiply(new BigDecimal(item.getQuantity()));
187	                totalWeight = totalWeight.add(itemWeight);
188	            }
189	        }
190	        return totalWeight;
191	    }
