193	    private BigDecimal calculateInsurance(BigDecimal subtotal, Region region) {
194	        BigDecimal percentage;
195	        BigDecimal limit = null;
196	
197	        switch (region) {
198	            case SOUTHEAST, SOUTH -> percentage = new BigDecimal("1");
199	            case MIDWEST -> percentage = new BigDecimal("1.5");
200	            case NORTH -> {
201	                percentage = new BigDecimal("2.5");
202	                limit = new BigDecimal("30");
203	            }
204	            case NORTHEAST -> {
205	                percentage = new BigDecimal("2");
206	                limit = new BigDecimal("30");
207	            }
208	            default -> percentage = BigDecimal.ZERO;
209	        }
210	
211	        BigDecimal insurance = PricingUtil.percentage(subtotal, percentage);
212	
213	        if (limit != null && insurance.compareTo(limit) > 0) {
214	            insurance = limit;
215	        }
216	
217	        return insurance;
218	    }
