220	    private void validatePaymentMethodConstraints(OrderRequestDTO request, BigDecimal total) {
221	        if (request.getPaymentMethod() == PaymentMethod.BANK_SLIP) {
222	            if (total.compareTo(new BigDecimal("1000")) > 0) {
223	                throw new OrderException("PAYMENT_METHOD_UNAVAILABLE", "BANK_SLIP not available for orders over R$ 1.000,00", HttpStatus.UNPROCESSABLE_ENTITY);
224	            }
225	        }
