 28	    public void validateOrderRequest(OrderRequestDTO request) {
 29	        // 1. Validate items, customer, and basic structure
 30	        validateItemsAndCustomer(request);
 31	
 32	        // 2. Check if products exist and valid
 33	        validateProducts(request.getItems());
 34	
 35	        // 3. Check club tier
 36	        validateClubTier(request.getClubTier());
 37	
