 42	        validateZipCode(request.getZipCode());
 43	
 44	        // 6. Check shipping method
 45	        validateShippingMethod(request.getShippingMethod());
 46	
 47	        // 7. Check payment method
 48	        validatePaymentMethod(request.getPaymentMethod());
 49	
 50	        // 8. Check installments
 51	        validateInstallments(request.getPaymentMethod(), request.getInstallments());
 52	
 53	        // 9. Validate payment method availability
 54	        validatePaymentMethodAvailability(request);
 55	
 56	        // 10. Validate coupon
 57	        validateCoupon(request, request.getItems());
