 60	    private void validateItemsAndCustomer(OrderRequestDTO request) {
 61	        if (request.getItems() == null || request.getItems().isEmpty()) {
 62	            throw new OrderException("INVALID_ORDER", "Cart is empty", HttpStatus.UNPROCESSABLE_ENTITY);
 63	        }
 64	
 65	        CustomerDTO customer = request.getCustomer();
 66	        if (customer == null || customer.getCpf() == null || customer.getEmail() == null) {
 67	            throw new OrderException("INVALID_ORDER", "Customer CPF and email are required", HttpStatus.UNPROCESSABLE_ENTITY);
 68	        }
 69	
 70	        Set<String> seenSkus = new HashSet<>();
 71	        for (OrderItemDTO item : request.getItems()) {
 72	            if (item.getSku() == null) {
 73	                throw new OrderException("INVALID_ORDER", "Item SKU is required", HttpStatus.UNPROCESSABLE_ENTITY);
 74	            }
 75	
 76	            if (seenSkus.contains(item.getSku())) {
 77	                throw new OrderException("INVALID_ORDER", "Duplicate SKU in cart", HttpStatus.UNPROCESSABLE_ENTITY);
 78	            }
 79	            seenSkus.add(item.getSku());
 80	
 81	            if (item.getQuantity() == null || item.getQuantity() <= 0) {
 82	                throw new OrderException("INVALID_ORDER", "Quantity must be positive", HttpStatus.UNPROCESSABLE_ENTITY);
 83	            }
 84	        }
 85	    }
